/* HTMX-compatible subset for AEGIS (hx-get, hx-post, hx-target, hx-swap, hx-swap-oob).
   Official htmx.min.js may replace this file when its SHA-256 is recorded in security/sbom/. */
(function () {
  function targetNode(el) {
    var sel = el.getAttribute("hx-target");
    if (!sel || sel === "this") return el;
    if (sel === "body") return document.body;
    return document.querySelector(sel) || el;
  }
  function swap(node, html, swapSpec) {
    var spec = (swapSpec || "innerHTML").toLowerCase();
    if (spec === "outerhtml") {
      node.outerHTML = html;
      return;
    }
    node.innerHTML = html;
  }
  function applyResponse(el, html) {
    var wrap = document.createElement("div");
    wrap.innerHTML = html;
    Array.prototype.slice.call(wrap.querySelectorAll("[hx-swap-oob]")).forEach(function (node) {
      var dest = node.id ? document.getElementById(node.id) : null;
      node.removeAttribute("hx-swap-oob");
      if (dest) dest.outerHTML = node.outerHTML;
      if (node.parentNode) node.parentNode.removeChild(node);
    });
    swap(targetNode(el), wrap.innerHTML, el.getAttribute("hx-swap"));
  }
  function markViewed(el) {
    var rec = el.getAttribute("data-record");
    if (el.type === "checkbox") el.checked = true;
    if (!rec) return;
    document.querySelectorAll("input.viewed-check").forEach(function (box) {
      if (box.getAttribute("data-record") === rec) box.checked = true;
    });
  }
  function headers(extra) {
    var h = { "HX-Request": "true", Accept: "text/html" };
    if (extra) Object.keys(extra).forEach(function (k) { h[k] = extra[k]; });
    return h;
  }
  document.addEventListener("click", function (ev) {
    var el = ev.target.closest("[hx-get]");
    if (!el) return;
    ev.preventDefault();
    if (el.type === "checkbox") el.checked = true;
    fetch(el.getAttribute("hx-get"), { headers: headers() })
      .then(function (r) {
        if (!r.ok) throw new Error("request failed");
        return r.text();
      })
      .then(function (html) {
        applyResponse(el, html);
        markViewed(el);
      });
  });
  document.addEventListener("submit", function (ev) {
    var form = ev.target.closest("form[hx-post]");
    if (!form) return;
    ev.preventDefault();
    var data = new FormData(form);
    var body = new URLSearchParams(data);
    var btn = form.querySelector("[type=submit]");
    var thread = form.classList.contains("ask-form") ? document.getElementById("engine-thread") : null;
    form.classList.add("is-waiting");
    if (btn) btn.disabled = true;
    if (thread) {
      var wait = document.createElement("div");
      wait.className = "chat-turn chat-pending";
      wait.id = "chat-wait";
      var asked = (data.get("q") || "").toString();
      wait.innerHTML =
        (asked ? '<p class="chat-bubble user"></p>' : "") +
        '<div class="chat-wait" aria-live="polite">' +
        '<span class="chat-spinner"></span>' +
        "Pack chat is reading the engine…</div>";
      if (asked) wait.querySelector(".chat-bubble.user").textContent = asked;
      thread.appendChild(wait);
      thread.scrollTop = thread.scrollHeight;
    }
    fetch(form.getAttribute("hx-post"), {
      method: "POST",
      headers: Object.assign(headers({ "Content-Type": "application/x-www-form-urlencoded" }), {}),
      body: body.toString(),
    })
      .then(function (r) { return r.text(); })
      .then(function (html) {
        applyResponse(form, html);
        form.reset();
      })
      .catch(function () {
        var pending = document.getElementById("chat-wait");
        if (pending) {
          pending.innerHTML =
            '<p class="chat-meta">Pack chat could not reach the engine.</p>';
        }
      })
      .finally(function () {
        form.classList.remove("is-waiting");
        if (btn) btn.disabled = false;
      });
  });
})();
